def text_of(unit):
    raw=unit.get('text','')
    if not isinstance(raw,str):
        raw=str(raw)
    return raw

def any_in(text,phrases):
    for phrase in phrases:
        if phrase in text:
            return True
    return False

def term_has(term,name):
    todo=[term]
    while todo:
        value=todo.pop()
        if isinstance(value,list) and value:
            if value[0]==name:
                return True
            i=1
            while i<len(value):
                if isinstance(value[i],list):
                    todo.append(value[i])
                i+=1
    return False

def add_unresolved(out,message):
    if message not in out:
        out.append(message)

def merge_ids(left,right):
    out=[]
    for value in left:
        if value not in out:
            out.append(value)
    for value in right:
        if value not in out:
            out.append(value)
    return out

def add_statement(out,term,ids):
    for statement in out:
        if statement.get('term')==term:
            statement['support_ids']=merge_ids(statement.get('support_ids',[]),ids)
            return
    out.append({'term':term,'support_ids':ids})

def make_union(items):
    if len(items)==1:
        return items[0]
    value=items[len(items)-1]
    i=len(items)-2
    while i>=0:
        value=['participant_union',items[i],value]
        i-=1
    return value

def make_bundle(items):
    if len(items)==1:
        return items[0]
    value=items[len(items)-1]
    i=len(items)-2
    while i>=0:
        value=['information_bundle',items[i],value]
        i-=1
    return value

def make_conditions(items):
    if not items:
        return ['no_condition']
    value=items[0]
    i=1
    while i<len(items):
        value=['and_condition',value,items[i]]
        i+=1
    return value

def ordered_ground_ids(answer,spans,byid):
    grounded=[]
    for evidence in answer.get('evidence',[]):
        unit_id=evidence.get('unit_id')
        unit=byid.get(unit_id)
        quote=evidence.get('quote','')
        if unit is not None and isinstance(quote,str) and quote and quote in text_of(unit):
            if unit_id not in grounded:
                grounded.append(unit_id)
    ordered=[]
    for span in spans:
        unit_id=span.get('id')
        if unit_id in grounded:
            ordered.append(unit_id)
    return ordered

def joined_text(ids,byid):
    parts=[]
    for unit_id in ids:
        unit=byid.get(unit_id)
        if unit is not None:
            parts.append(text_of(unit))
    return ' '.join(parts)

def personnel_terms(text):
    owner=['receiving_party']
    items=[]
    if 'employee' in text or 'member of its staff' in text or 'members of its staff' in text or 'personnel' in text:
        items.append(['employees_of',owner])
    if 'contractor' in text:
        items.append(['independent_contractors_of',owner])
    if 'consultant' in text:
        items.append(['consultants_of',owner])
    if 'agent' in text:
        items.append(['agents_of',owner])
    if 'director' in text:
        items.append(['directors_of',owner])
    if 'officer' in text or 'official' in text:
        items.append(['officers_of',owner])
    if 'accountant' in text:
        items.append(['accountants_of',owner])
    if any_in(text,['legal adviser','legal advisor','attorney','legal counsel']):
        items.append(['legal_advisors_of',owner])
    if any_in(text,['financial adviser','financial advisor']):
        items.append(['financial_advisors_of',owner])
    if any_in(text,['professional adviser','professional advisor']):
        items.append(['professional_advisors_of',owner])
    if 'representative' in text:
        items.append(['representatives_of',owner])
    unique=[]
    for item in items:
        if item not in unique:
            unique.append(item)
    return unique

def disclosure_condition(text):
    conditions=[]
    if any_in(text,['need to know','need-to-know','need-to know']):
        conditions.append(['need_to_know','source-stated need to know'])
    if any_in(text,['written agreement','confidentiality agreement','confidentiality agreements','bound to a duty of confidentiality','bound by obligations of confidentiality','treat the confidential information in accordance','obligations assumed herein','obligated to protect']):
        conditions.append(['confidentiality_bound','source-stated confidentiality protection'])
    if any_in(text,['extent absolutely necessary','only to the extent necessary','extent necessary','disclosure is necessary','as deemed necessary']):
        conditions.append(['extent_necessary','source-stated purpose'])
    return make_conditions(conditions)

def permission_evidence_ids(ids,byid):
    out=[]
    for unit_id in ids:
        text=text_of(byid.get(unit_id)).casefold()
        personnel=any_in(text,['employee','staff','contractor','consultant','agent','representative','official','director','officer','adviser','advisor','accountant'])
        grant=any_in(text,['may disclose','may be disclosed','will disclose','restrict disclosure','restrict access','disclose information it receives','provided that the recipient has a written agreement'])
        condition=any_in(text,['need to know','need-to-know','confidentiality','obligations assumed','extent absolutely necessary'])
        if personnel and (grant or condition):
            out.append(unit_id)
        elif grant and text.strip().endswith(':'):
            out.append(unit_id)
    return out

def prohibition_evidence_ids(ids,byid):
    out=[]
    for unit_id in ids:
        text=text_of(byid.get(unit_id)).casefold()
        negative=any_in(text,['shall not disclose','will not disclose','not disclose','without prior written consent','without the express written consent','without prior written approval','will not without'])
        target=any_in(text,['third party','third parties','other person','other entity','to others','any other person','any other organization'])
        if negative and target:
            out.append(unit_id)
    return out

def authorization_exceptions(text):
    if any_in(text,['prior written consent','express written consent','prior written approval','prior written agreement','without consent']):
        return ['exception_set',['authorization_exception','source-stated written authorization']]
    return ['no_exceptions']

def information_scope(text):
    items=[['confidential_information']]
    if 'copy' in text or 'copies' in text or 'reproduction' in text or 'records thereof' in text:
        items.append(['copies_of',['confidential_information']])
    if any_in(text,['notes','abstracts','extracts','analyses','studies','summaries','derivative']):
        items.append(['derivative_materials_of',['confidential_information']])
    unique=[]
    for item in items:
        if item not in unique:
            unique.append(item)
    return make_bundle(unique)

def disposal_action_present(text):
    return any_in(text,['return','returned']) and not any_in(text,['return receipt','tax return']) or any_in(text,['destroy','destruction','destruct'])

def trigger_from_text(text):
    triggers=[]
    if any_in(text,['termination of service','service terminates','relationship with the']) and 'service' in text:
        triggers.append(['service_termination'])
    if any_in(text,['business relationship is not entered','business relationship has not been entered']):
        triggers.append(['relationship_endpoint','failure to enter a business relationship by the source-stated deadline'])
    elif 'business relation' in text and any_in(text,['termination','expiration']):
        triggers.append(['relationship_endpoint','termination or expiration of the business relationship'])
    elif any_in(text,['termination of this agreement','termination of the agreement','expiration of this agreement','expiration or termination ofthis agreement','expiration or termination of this agreement']):
        triggers.append(['agreement_termination'])
    if any_in(text,['completion of the purpose','completion of its purpose']):
        triggers.append(['purpose_completion'])
    if 'request' in text:
        triggers.append(['request_by',['disclosing_party']])
    if not triggers:
        return None
    value=triggers[0]
    i=1
    while i<len(triggers):
        value=['trigger_alternative',value,triggers[i]]
        i+=1
    return value

def existing_disposal_for_ids(statements,ids):
    for statement in statements:
        term=statement.get('term')
        if isinstance(term,list) and term and term[0]=='disposal_obligation':
            for unit_id in statement.get('support_ids',[]):
                if unit_id in ids:
                    return True
    return False

def retention_condition(text):
    if 'applicable law' in text or 'required by law' in text:
        return ['retention_condition','record copy required by applicable law']
    if 'archival' in text:
        return ['retention_condition','source-stated archival purpose']
    if 'single copy' in text:
        return ['retention_condition','single copy for the source-stated purpose']
    return ['retention_condition','source-stated limited retention']

def apply(inputs,premises):
    spans=inputs.get('source_spans',[])
    source_output=inputs.get('source_output',{})
    byid={}
    for span in spans:
        byid[span.get('id')]=span
    answers={}
    for answer in inputs.get('semantic_answers',[]):
        answers[answer.get('id')]=answer
    unresolved=[]
    for message in source_output.get('unresolved',[]):
        add_unresolved(unresolved,message)
    disposal_answer=answers.get('complete_source_disposal')
    disposal_ids=[]
    disposal_text=''
    if disposal_answer is not None:
        disposal_ids=ordered_ground_ids(disposal_answer,spans,byid)
        disposal_text=joined_text(disposal_ids,byid).casefold()
    statements=[]
    for statement in source_output.get('statements',[]):
        term=statement.get('term')
        replace_bad=False
        if isinstance(term,list) and term and term[0]=='disposal_obligation' and term_has(term,'purpose_completion'):
            overlap=False
            for unit_id in statement.get('support_ids',[]):
                if unit_id in disposal_ids:
                    overlap=True
            if overlap and any_in(disposal_text,['business relationship is not entered','business relationship has not been entered']):
                replace_bad=True
        if not replace_bad:
            statements.append(statement)
    disclosure=answers.get('complete_source_disclosure')
    if disclosure is None:
        add_unresolved(unresolved,'The complete-source disclosure structure was not read.')
    else:
        disclosure_ids=ordered_ground_ids(disclosure,spans,byid)
        choice=disclosure.get('choice')
        if choice=='unknown' or not disclosure_ids:
            add_unresolved(unresolved,'The complete-source disclosure structure lacks a definite grounded reading.')
        else:
            positive_permission=choice in ('permissions_and_prohibitions','permissions_only')
            positive_prohibition=choice in ('permissions_and_prohibitions','prohibitions_only')
            permission_ids=permission_evidence_ids(disclosure_ids,byid)
            prohibition_ids=prohibition_evidence_ids(disclosure_ids,byid)
            if positive_permission:
                permission_text=joined_text(permission_ids,byid).casefold()
                recipients=personnel_terms(permission_text)
                if recipients:
                    permission=['permission',['receiving_party'],['disclose',['confidential_information'],make_union(recipients)],disclosure_condition(permission_text)]
                    add_statement(statements,permission,permission_ids)
                else:
                    add_unresolved(unresolved,'A grounded disclosure authorization was observed, but its recipient class was not resolved.')
            if positive_prohibition:
                prohibition_text=joined_text(prohibition_ids,byid).casefold()
                if prohibition_ids:
                    if any_in(prohibition_text,['third party','third parties']):
                        recipient=['third_parties']
                    else:
                        recipient=['outsiders_to',['receiving_party']]
                    prohibition=['prohibition',['receiving_party'],['disclose',['confidential_information'],recipient],['no_condition'],authorization_exceptions(prohibition_text)]
                    add_statement(statements,prohibition,prohibition_ids)
                else:
                    add_unresolved(unresolved,'A grounded disclosure prohibition was observed, but its operative target was not resolved.')
            if choice=='no_disclosure_norm':
                for statement in statements:
                    term=statement.get('term')
                    if isinstance(term,list) and term and term[0] in ('permission','prohibition') and term_has(term,'disclose'):
                        add_unresolved(unresolved,'The complete-source disclosure reading conflicts with a preserved operative disclosure root.')
    if disposal_answer is None:
        add_unresolved(unresolved,'The complete-source disposal structure was not read.')
    else:
        disposal_choice=disposal_answer.get('choice')
        if disposal_choice=='unknown' or not disposal_ids:
            add_unresolved(unresolved,'The complete-source disposal structure lacks a definite grounded reading.')
        elif disposal_choice!='no_disposal_duty':
            positions=[]
            i=0
            while i<len(disposal_ids):
                unit_id=disposal_ids[i]
                if disposal_action_present(text_of(byid.get(unit_id)).casefold()):
                    positions.append(i)
                i+=1
            if not positions:
                add_unresolved(unresolved,'A disposal duty was observed, but no grounded return-or-destroy action was resolved.')
            p=0
            while p<len(positions):
                start=positions[p]
                end=len(disposal_ids)
                if p+1<len(positions):
                    end=positions[p+1]
                cluster=[]
                j=start
                while j<end:
                    cluster.append(disposal_ids[j])
                    j+=1
                cluster_text=joined_text(cluster,byid).casefold()
                trigger=trigger_from_text(cluster_text)
                if trigger is None:
                    add_unresolved(unresolved,'A grounded disposal action lacks a resolved source trigger.')
                elif not existing_disposal_for_ids(statements,cluster):
                    action_text=text_of(byid.get(cluster[0])).casefold()
                    info=information_scope(action_text)
                    do_return='return' in action_text
                    do_destroy=any_in(action_text,['destroy','destruction','destruct']) and 'not destroyed' not in action_text
                    if do_return and do_destroy:
                        action=['action_alternative',['return_to',info,['disclosing_party']],['destroy',info]]
                    elif do_return:
                        action=['return_to',info,['disclosing_party']]
                    else:
                        action=['destroy',info]
                    add_statement(statements,['disposal_obligation',['receiving_party'],action,trigger,['no_exceptions']],cluster)
                p+=1
        elif existing_disposal_for_ids(statements,disposal_ids):
            add_unresolved(unresolved,'The complete-source disposal reading conflicts with a preserved disposal obligation.')
    retention=answers.get('complete_source_retention')
    if retention is None:
        add_unresolved(unresolved,'The complete-source post-disposal retention structure was not read.')
    else:
        retention_ids=ordered_ground_ids(retention,spans,byid)
        retention_choice=retention.get('choice')
        if retention_choice=='unknown' or not retention_ids:
            add_unresolved(unresolved,'The complete-source retention structure lacks a definite grounded reading.')
        else:
            retention_text=joined_text(retention_ids,byid).casefold()
            if retention_choice in ('retention_permission_only','permission_and_prohibition'):
                info=information_scope(retention_text)
                add_statement(statements,['retention_permission',['receiving_party'],info,['after_disposal'],retention_condition(retention_text)],retention_ids)
            if retention_choice in ('retention_prohibition_only','permission_and_prohibition'):
                info=information_scope(retention_text)
                add_statement(statements,['retention_prohibition',['receiving_party'],info,['after_disposal']],retention_ids)
            if retention_choice=='no_retention_rule':
                for statement in statements:
                    term=statement.get('term')
                    if isinstance(term,list) and term and term[0] in ('retention_permission','retention_exception','retention_prohibition'):
                        add_unresolved(unresolved,'The complete-source retention reading conflicts with a preserved explicit retention root.')
    complete=bool(source_output.get('complete',False)) and not unresolved
    return {'statements':statements,'complete':complete,'unresolved':unresolved}

