def is_candidate(unit):
    raw=unit.get('text','')
    if not isinstance(raw,str):
        raw=str(raw)
    t=raw.casefold()
    protected='confidential information' in t
    personnel=('employee' in t or 'contractor' in t)
    disclosure=('disclos' in t or 'restrict access' in t)
    grant=('may be disclosed' in t or 'may disclose' in t or 'restrict access' in t or 'except in confidence' in t or 'except to' in t)
    need=('need to know' in t or 'need-to-know' in t or 'need-to know' in t)
    bound=('confidentiality agreement' in t or 'confidentiality agreements' in t or 'subject to written confidentiality' in t or 'bound by' in t or 'obligated to protect' in t or 'treat the confidential information as confidential' in t)
    return protected and personnel and disclosure and grant and need and bound

def context_relevant(unit):
    raw=unit.get('text','')
    if not isinstance(raw,str):
        raw=str(raw)
    t=raw.casefold()
    return 'confidential information' in t and ('disclos' in t or 'third part' in t or 'restrict access' in t)

def unit_text(unit):
    raw=unit.get('text','')
    if not isinstance(raw,str):
        raw=str(raw)
    return raw

def any_in(text,phrases):
    for phrase in phrases:
        if phrase in text:
            return True
    return False

def personnel_reference(text):
    return any_in(text,['employee','contractor','consultant','agent','representative','official','director','officer','adviser','advisor','accountant'])

def disclosure_marker(text):
    return any_in(text,['may disclose','may be disclosed','may share','restrict disclosure','restrict access','except in confidence','except to such'])

def disclosure_governor(text):
    if text.endswith(':') and any_in(text,['may disclose','may be disclosed','following persons','following entities']):
        return True
    return any_in(text,['following are deemed confidential information','following shall be deemed confidential information'])

def find_disclosure_governor(spans,index):
    j=index-1
    distance=0
    while j>=0 and distance<20:
        text=unit_text(spans[j]).casefold().strip()
        if disclosure_governor(text):
            return j
        if any_in(text,['non-disclosure','remedies','governing law','entire agreement']) and not text.startswith(''):
            return -1
        j-=1
        distance+=1
    return -1

def disclosure_windows(spans):
    out=[]
    i=0
    while i<len(spans):
        text=unit_text(spans[i]).casefold()
        if personnel_reference(text):
            governor=-1
            if not disclosure_marker(text):
                governor=find_disclosure_governor(spans,i)
            ids=[]
            if disclosure_marker(text):
                ids.append(spans[i].get('id'))
            elif governor>=0:
                ids.append(spans[governor].get('id'))
                ids.append(spans[i].get('id'))
            if ids:
                out.append({'id':'personnel_window_'+str(spans[i].get('id')),'unit_ids':ids})
        i+=1
    return out

def disposal_action(text):
    return ('confidential information' in text or 'such confidential information' in text) and ('return' in text or 'destroy' in text or 'destruct' in text)

def endpoint_trigger(text):
    return any_in(text,['termination','expiration','completion of the purpose','business relationship is not entered','service terminates'])

def request_trigger(text):
    return 'request' in text

def disposal_windows(spans):
    out=[]
    i=0
    while i<len(spans):
        text=unit_text(spans[i]).casefold().strip()
        if disposal_action(text):
            ids=[spans[i].get('id')]
            has_trigger=endpoint_trigger(text) or request_trigger(text)
            if not has_trigger or text.endswith(':'):
                j=i+1
                steps=0
                while j<len(spans) and steps<4:
                    child=unit_text(spans[j]).casefold()
                    if endpoint_trigger(child) or request_trigger(child):
                        ids.append(spans[j].get('id'))
                        has_trigger=True
                    elif has_trigger:
                        break
                    j+=1
                    steps+=1
            if has_trigger:
                out.append({'id':'disposal_window_'+str(spans[i].get('id')),'unit_ids':ids})
        i+=1
    return out

